import pandas as pd

def load_spreadsheet(file_path):
    try:
        df = pd.read_csv(file_path) # Change this line for different file formats
        return df
    except Exception as e:
        print("Error loading spreadsheet:", str(e))
        return None

def sort_spreadsheet(df, columns):
    try:
        df.sort_values(columns, inplace=True)
    except Exception as e:
        print("Error sorting spreadsheet:", str(e))

def filter_spreadsheet(df, column, value):
    try:
        df = df[df[column] == value]
        return df
    except Exception as e:
        print("Error filtering spreadsheet:", str(e))
        return None

def find_duplicates(df, columns):
    try:
        duplicates = df.duplicated(subset=columns, keep=False)
        duplicate_rows = df[duplicates]
        return duplicate_rows
    except Exception as e:
        print("Error finding duplicates:", str(e))
        return None

def calculate_average(df, columns, avg_column):
    try:
        avg_values = df.groupby(columns)[avg_column].mean()
        return avg_values
    except Exception as e:
        print("Error calculating average:", str(e))
        return None

def display_duplicates(duplicate_rows):
    if duplicate_rows is not None:
        print("Duplicate rows:")
        print(duplicate_rows)
    else:
        print("No duplicate rows found.")

def display_average(avg_values):
    if avg_values is not None:
        print("Average values:")
        print(avg_values)
    else:
        print("No average values calculated.")

def main():
    file_path = input("Enter the file path of the spreadsheet: ")
    columns = input("Enter the columns to consider for duplicates (comma-separated): ").split(",")
    avg_column = input("Enter the column to calculate average: ")

    df = load_spreadsheet(file_path)
    if df is None:
