import numpy as np

class NaiveBayes:
    def __init__(self):
        self.classes = None
        self.class_probs = None
        self.feature_probs = None
        self.feature_means = None

    def fit(self, X, y):
        self.classes = np.unique(y)
        self.class_probs = np.zeros(len(self.classes))
        self.feature_probs = {}
        self.feature_means = {}

        for i, c in enumerate(self.classes):
            X_c = X[y == c]
            self.class_probs[i] = len(X_c) / len(X)

            self.feature_probs[c] = {}
            self.feature_means[c] = np.nanmean(X_c, axis=0)

            for j in range(X.shape[1]):
                feature_values = np.unique(X_c[:, j])
                self.feature_probs[c][j] = {}

                for value in feature_values:
                    count = np.sum(X_c[:, j] == value)
                    self.feature_probs[c][j][value] = (count + 1) / (len(X_c) + len(feature_values))

    def predict(self, X):
        predictions = []
        for x in X:
            class_scores = []
            for i, c in enumerate(self.classes):
                score = np.log(self.class_probs[i])
                for j, value in enumerate(x):
                    if np.isnan(value):
                        value = self.feature_means[c][j]
                    if value in self.feature_probs[c][j]:
                        score += np.log(self.feature_probs[c][j][value])
                    else:
                        score += np.log(1 / (len(self.feature_probs[c][j]) + 1))  # Laplace smoothing
                class_scores.append(score)
            predictions.append(self.classes[np.argmax(class_scores)])
        return predictions
```

